CREATE TABLE IF NOT EXISTS seasons(id TEXT PRIMARY KEY, name TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('UPCOMING','CURRENT','FINISHED')));
CREATE UNIQUE INDEX IF NOT EXISTS one_current_season ON seasons(status) WHERE status='CURRENT';
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, telegram_id TEXT UNIQUE NOT NULL, username TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'PLAYER' CHECK(role IN ('PLAYER','ORGANIZER','ADMIN')), banned INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL, avatar TEXT, profile_photo TEXT, city TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ratings(user_id TEXT PRIMARY KEY REFERENCES users(id), rating INTEGER NOT NULL DEFAULT 1000, highest_rating INTEGER NOT NULL DEFAULT 1000, games INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0, tournament_wins INTEGER NOT NULL DEFAULT 0, podiums INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rating_history(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), season_id TEXT REFERENCES seasons(id), rating INTEGER NOT NULL, match_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tournaments(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', organizer_id TEXT NOT NULL REFERENCES users(id), location TEXT NOT NULL, start_at TEXT NOT NULL, registration_deadline TEXT NOT NULL, max_players INTEGER NOT NULL CHECK(max_players BETWEEN 2 AND 64), format TEXT NOT NULL DEFAULT 'SINGLE_ELIMINATION', status TEXT NOT NULL CHECK(status IN ('DRAFT','OPEN','FULL','LIVE','FINISHED','CANCELLED')), qr_token TEXT NOT NULL UNIQUE, season_id TEXT REFERENCES seasons(id), champion_id TEXT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tournament_players(tournament_id TEXT REFERENCES tournaments(id), user_id TEXT REFERENCES users(id), joined_at TEXT NOT NULL, PRIMARY KEY(tournament_id,user_id));
CREATE TABLE IF NOT EXISTS matches(id TEXT PRIMARY KEY, player_a TEXT NOT NULL REFERENCES users(id), player_b TEXT NOT NULL REFERENCES users(id), score_a INTEGER NOT NULL, score_b INTEGER NOT NULL, winner TEXT REFERENCES users(id), loser TEXT REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('PENDING','CONFIRMED','REJECTED','CANCELLED')), tournament_id TEXT REFERENCES tournaments(id), created_at TEXT NOT NULL, confirmed_at TEXT, rating_change_a INTEGER, rating_change_b INTEGER, request_key TEXT UNIQUE, reward_eligible INTEGER NOT NULL DEFAULT 0, CHECK(player_a<>player_b));
CREATE TABLE IF NOT EXISTS tournament_matches(id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), round INTEGER NOT NULL, position INTEGER NOT NULL, player_a TEXT REFERENCES users(id), player_b TEXT REFERENCES users(id), winner TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'WAITING', score_a INTEGER, score_b INTEGER, match_id TEXT REFERENCES matches(id), UNIQUE(tournament_id,round,position));
CREATE TABLE IF NOT EXISTS stickers(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, image_url TEXT NOT NULL, rarity TEXT NOT NULL CHECK(rarity IN ('COMMON','UNCOMMON','RARE','EPIC','LEGENDARY','MYTHIC')), season TEXT REFERENCES seasons(id), type TEXT NOT NULL CHECK(type IN ('COLLECTION','BATTLE')), owner_id TEXT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_stickers(user_id TEXT REFERENCES users(id), sticker_id TEXT REFERENCES stickers(id), quantity INTEGER NOT NULL CHECK(quantity>=0), first_received_at TEXT NOT NULL, last_received_at TEXT NOT NULL, PRIMARY KEY(user_id,sticker_id));
CREATE TABLE IF NOT EXISTS packs(id TEXT PRIMARY KEY, name TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), probabilities TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pack_openings(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), pack_id TEXT NOT NULL REFERENCES packs(id), rewards TEXT NOT NULL, request_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS pingpoint_transactions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), amount INTEGER NOT NULL, type TEXT NOT NULL, reference_id TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,type,reference_id));
CREATE TRIGGER IF NOT EXISTS ledger_no_update BEFORE UPDATE ON pingpoint_transactions BEGIN SELECT RAISE(ABORT,'Ledger entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS ledger_no_delete BEFORE DELETE ON pingpoint_transactions BEGIN SELECT RAISE(ABORT,'Ledger entries are immutable'); END;
CREATE TABLE IF NOT EXISTS achievements(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, metric TEXT NOT NULL, threshold INTEGER NOT NULL, reward INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS user_achievements(user_id TEXT REFERENCES users(id), achievement_id TEXT REFERENCES achievements(id), created_at TEXT NOT NULL, PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), type TEXT NOT NULL, message TEXT NOT NULL, read_at TEXT, delivered_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_logs(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS config(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS match_player_a ON matches(player_a,created_at);
CREATE INDEX IF NOT EXISTS match_player_b ON matches(player_b,created_at);
CREATE INDEX IF NOT EXISTS ledger_user ON pingpoint_transactions(user_id,created_at);
CREATE INDEX IF NOT EXISTS notification_user ON notifications(user_id,created_at);
CREATE INDEX IF NOT EXISTS rating_history_user ON rating_history(user_id,created_at);
